// Some portions generated by Codex
package org.eclipse.rdf4j.sail.rdfparser;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.StringReader;
import java.util.List;
import java.util.stream.Stream;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.rio.RDFParseException;
import org.eclipse.rdf4j.rio.RDFParser;
import org.eclipse.rdf4j.rio.Rio;
import org.eclipse.rdf4j.rio.helpers.BasicParserSettings;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

/** Tests the real Rio recursion boundary as well as the outer document interface. */
class RdfParserSafetyTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final List<RDFFormat> FORMATS = List.of(RDFFormat.TURTLE, RDFFormat.TRIG,
			RDFFormat.NTRIPLES, RDFFormat.NQUADS);

	static Stream<RDFFormat> formats() {
		return FORMATS.stream();
	}

	static Stream<Arguments> structures() {
		return Stream.of(RDFFormat.TURTLE, RDFFormat.TRIG)
				.flatMap(format -> Stream.of("list", "blank", "reified", "annotation")
						.map(kind -> Arguments.of(format, kind)));
	}

	private static String nested(String kind, int depth) {
		String object = switch (kind) {
		case "list" -> "( ".repeat(depth) + "<urn:o>" + " )".repeat(depth);
		case "blank" -> "[ <urn:p> ".repeat(depth) + "<urn:o>" + " ]".repeat(depth);
		case "reified" -> "<< <urn:s> <urn:p> ".repeat(depth) + "<urn:o>" + " >>".repeat(depth);
		case "annotation" -> "<urn:o>" + " {| <urn:note> <urn:o>".repeat(depth) + " |}".repeat(depth);
		default -> "<<( <urn:s> <urn:p> ".repeat(depth) + "<urn:o>" + " )>>".repeat(depth);
		};
		return "<urn:s> <urn:p> " + object + " .";
	}

	private static RDFParser raw(RDFFormat format, int limit) {
		RDFParser parser = Rio.createParser(format);
		parser.set(BasicParserSettings.MAX_NESTING_DEPTH, limit);
		parser.set(BasicParserSettings.VERIFY_DATATYPE_VALUES, false);
		return parser;
	}

	@ParameterizedTest
	@MethodSource("formats")
	void tripleTermDepthIsCheckedInsideRioWithoutPreflight(RDFFormat format) throws Exception {
		RDFParser parser = raw(format, 4);
		assertTrue(parser.getSupportedSettings().contains(BasicParserSettings.MAX_NESTING_DEPTH));
		parser.parse(new StringReader(nested("term", 4)), "");
		var failure = assertThrows(RDFParseException.class,
				() -> parser.parse(new StringReader(nested("term", 5)), ""));
		assertTrue(failure.getMessage().contains("nesting"), failure::getMessage);
		// An aborted invocation must not leave the reusable parser's nesting counter incremented.
		parser.parse(new StringReader(nested("term", 4)), "");
	}

	@ParameterizedTest
	@MethodSource("structures")
	void allRecursiveTurtleStructuresAreBounded(RDFFormat format, String kind) throws Exception {
		RDFParser parser = raw(format, 4);
		parser.parse(new StringReader(nested(kind, 4)), "");
		var failure = assertThrows(RDFParseException.class,
				() -> parser.parse(new StringReader(nested(kind, 5)), ""));
		assertTrue(failure.getMessage().contains("nesting"), failure::getMessage);
		parser.parse(new StringReader(nested(kind, 1)), "");
	}

	@ParameterizedTest
	@MethodSource("formats")
	void syntaxFailuresDoNotDependOnDatatypeValidation(RDFFormat format) {
		RDFParser parser = raw(format, 4);
		for (String object : List.of("\"\\q\"", "\"\\uZZZZ\"", "<urn:bad\\uZZZZ>", "\"\"^^\"\"")) {
			assertThrows(RDFParseException.class,
					() -> parser.parse(new StringReader("<urn:s> <urn:p> " + object + " ."), ""), object);
		}
	}

	@ParameterizedTest
	@MethodSource("formats")
	void illTypedLiteralsRemainRepresentable(RDFFormat format) throws Exception {
		String text = "<urn:s> <urn:p> \"not-an-integer\"^^<http://www.w3.org/2001/XMLSchema#integer> .";
		raw(format, 4).parse(new StringReader(text), "");
		assertEquals(1, new RdfDocumentParser(RdfParseOptions.DEFAULT).parse(VF.createLiteral(text),
				VF.createLiteral(format.getDefaultMIMEType()), null).size());
	}

	@ParameterizedTest
	@MethodSource("formats")
	void noPartialRowsEscapeSyntaxFailure(RDFFormat format) {
		String text = "<urn:good> <urn:p> <urn:o> .\n<urn:bad> <urn:p> \"\\q\" .";
		var parser = new RdfDocumentParser(RdfParseOptions.DEFAULT);
		assertThrows(QueryEvaluationException.class, () -> parser.parse(VF.createLiteral(text),
				VF.createLiteral(format.getDefaultMIMEType()), null));
		assertThrows(QueryEvaluationException.class, () -> parser.parseStatements(VF.createLiteral(text),
				VF.createLiteral(format.getDefaultMIMEType()), null, false));
	}

	@Test
	void malformedNumericExponentIsSyntaxNotDatatypeValidation() {
		assertThrows(RDFParseException.class,
				() -> raw(RDFFormat.TURTLE, 4).parse(new StringReader("<urn:s> <urn:p> 1e ."), ""));
	}

	@Test
	void validEscapesAndPrefixedDatatypesArePreserved() {
		String text = "PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n"
				+ "<urn:s> <urn:p> \"line\\nquote\\\"slash\\\\\\u00E5\\U0001F600\"^^xsd:string .";
		var model = new RdfDocumentParser(RdfParseOptions.DEFAULT).parse(VF.createLiteral(text),
				VF.createLiteral("text/turtle"), null);
		assertEquals("line\nquote\"slash\\å😀", model.iterator().next().getObject().stringValue());
	}
}
